 public async Task<object> Start(){flow.Cancel();flow.Dispose();flow=new();var ct=flow.Token;security=userId=serviceToken="";imported.Clear();deviceId=Convert.ToHexString(RandomNumberGenerator.GetBytes(8));var uri=new Uri("https://account.xiaomi.com");cookies.Add(uri,new Cookie("sdkVersion","accountsdk-18.8.15"));cookies.Add(uri,new Cookie("deviceId",deviceId));var args=new Dictionary<string,string>{{"_qrsize","480"},{"qs","%3Fsid%3Dxiaomiio%26_json%3Dtrue"},{"bizDeviceType",""},{"callback","https://sts.api.io.mi.com/sts"},{"_hasLogo","false"},{"theme",""},{"needTheme","false"},{"showActiveX","false"},{"serviceParam","{\"checkSafePhone\":false,\"checkSafeAddress\":false,\"lsrp_score\":0.0}"},{"sid","xiaomiio"},{"_locale","en_GB"},{"_dc",DateTimeOffset.UtcNow.ToUnixTimeMilliseconds().ToString()}};var data=Json(await Get("https://account.xiaomi.com/longPolling/loginUrl?"+Query(args),ct));pollUrl=Trusted((string?)data["lp"]??"").AbsoluteUri;var qr=await Get((string?)data["qr"]??"",ct);if(qr.Length>2*1024*1024)throw new IOException("二维码图片过大");return new{image="data:image/png;base64,"+Convert.ToBase64String(qr),timeout=(int?)data["timeout"]??300};}
