;CuktechProtocol.Token(token);imported[normalized]=(d["name"]?.ToString()??"酷态科 10 Ultra",token);}catch(ArgumentException){}}
  return new{pending=false,devices=imported.Select(d=>new{mac=d.Key,name=d.Value.Name}).ToArray()};}
 internal static string Signature(Dictionary<string,string> values,string signed)=>Convert.ToBase64String(SHA1.HashData(Encoding.UTF8.GetBytes("POST&/home/device_list&"+string.Join("&",values.Select(x=>x.Key+"="+x.Value))+"&"+signed)));
 internal static byte[] Rc4(byte[] key,byte[] data){if(key.Length==0)throw new ArgumentException("Empty key");int[] s=Enumerable.Range(0,256).ToArray();int j=0;for(int i=0;i<256;i++){j=(j+s[i]+key[i%key.Length])&255;(s[i],s[j])=(s[j],s[i]);}int x=0;j=0;var output=new byte[data.Length];for(int n=-1024;n<data.Length;n++){x=(x+1)&255;j=(j+s[x])&255;(s[x],s[j])=(s[j],s[x]);if(n>=0)output[n]=(byte)(data[n]^s[(s[x]+s[j])&255]);}return output;}
